SELECT p.gender, CASE WHEN p.age BETWEEN 53 AND 63 THEN '53-63' ELSE 'Other' END AS age_group, d.name AS diagnosis, SUM(CASE WHEN a.los <= 7 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(a.deathtime), 0) AS mortality_rate_under_7_days, COUNT(DISTINCT CASE WHEN a.deathtime IS NOT NULL THEN a.subject_id END)::FLOAT / NULLIF(COUNT(a.subject_id), 0) AS total_deaths, AVG(a.deathtime - a.admittime) AS average_length_of_stay, SUM(CASE WHEN a.los > 7 THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(a.deathtime), 0) AS mortality_rate_over_7_days, SUM(CASE WHEN d.name = 'Sepsis' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.name), 0) AS sepsis_mortality_rate, SUM(CASE WHEN d.name = 'Shock' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.name), 0) AS shock_mortality_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND p.age = 58 AND d.name IN ('Sepsis', 'Shock') GROUP BY p.gender, age_group, diagnosis;